const max = 5;
type stack = record
        items : array[1..max] of integer;
        top   : integer;          { 0 means empty }
     end;

procedure push(var s : stack; x : integer);
begin
  if s.top = max then writeln('overflow')
  else begin
    s.top := s.top + 1;
    s.items[s.top] := x
  end
end;

function pop(var s : stack) : integer;
begin
  if s.top = 0 then begin writeln('underflow'); pop := 0 end
  else begin
    pop := s.items[s.top];
    s.top := s.top - 1
  end
end;
```

This code is an example of logic: no Pascal compiler was used, and its logic was checked by an executed Python translation (after push 4, push 7, push 9, two pops give 9 then 7 and leave 4). The var parameter s is passed by reference, so that the stack changes in the caller.
